"g|zh|HSK 2|Frasa 的 (de)":[["我要红的。","Wǒ yào hóng de.","Aku mau yang merah.","的","yang merah"],["这本书不是我的。","Zhè běn shū bù shì wǒ de.","Buku ini bukan milikku.","的","milikku"],["这个手机是谁的？","Zhè ge shǒujī shì shuí de?","Ponsel ini milik siapa?","的","milik siapa"],["这个大的太贵了。","Zhè ge dà de tài guì le.","Yang besar ini terlalu mahal.","的","Yang besar"],["他做的面条很好吃。","Tā zuò de miàntiáo hěn hǎochī.","Mi buatannya sangat enak.","的","Mi buatannya"],["我喜欢吃妈妈做的菜。","Wǒ xǐhuan chī māma zuò de cài.","Aku suka makan masakan buatan ibu.","的","masakan buatan ibu"],["你喝的是什么？","Nǐ hē de shì shénme?","Yang kamu minum itu apa?","的","Yang kamu minum"],["这是我昨天买的。","Zhè shì wǒ zuótiān mǎi de.","Ini kubeli kemarin.","的","kubeli kemarin"],["穿白衣服的是我老师。","Chuān bái yīfu de shì wǒ lǎoshī.","Yang memakai baju putih adalah guruku.","的","Yang memakai baju putih"],["在教室里学习的学生很多。","Zài jiàoshì li xuéxí de xuéshēng hěn duō.","Siswa yang belajar di kelas sangat banyak.","的","Siswa yang belajar di kelas"],["卖水果的商店在学校旁边。","Mài shuǐguǒ de shāngdiàn zài xuéxiào pángbiān.","Toko yang menjual buah ada di samping sekolah.","的","Toko yang menjual buah"]],
"g|zh|HSK 2|Kata Bantu 一下 (yíxià)":[["我看一下。","Wǒ kàn yíxià.","Aku lihat sebentar.","一下","sebentar"],["请你等一下。","Qǐng nǐ děng yíxià.","Tolong tunggu sebentar.","一下","sebentar"],["我想休息一下。","Wǒ xiǎng xiūxi yíxià.","Aku ingin istirahat sebentar.","一下","sebentar"],["你去问一下老师。","Nǐ qù wèn yíxià lǎoshī.","Coba tanya guru sebentar.","一下","sebentar"],["让我想一下。","Ràng wǒ xiǎng yíxià.","Biar aku pikir sebentar.","一下","sebentar"],["请你再说一下。","Qǐng nǐ zài shuō yíxià.","Tolong katakan sekali lagi.","一下","sekali lagi"],["你来看一下这个手表。","Nǐ lái kàn yíxià zhè ge shǒubiǎo.","Coba lihat jam tangan ini.","一下","Coba"],["我去洗一下衣服。","Wǒ qù xǐ yíxià yīfu.","Aku pergi mencuci baju sebentar.","一下","sebentar"],["你能帮助我一下吗？","Nǐ néng bāngzhù wǒ yíxià ma?","Bisakah kamu membantuku sebentar?","一下","sebentar"],["请你介绍一下你的家。","Qǐng nǐ jièshào yíxià nǐ de jiā.","Tolong perkenalkan keluargamu sebentar.","一下","sebentar"],["我们看一下今天的报纸。","Wǒmen kàn yíxià jīntiān de bàozhǐ.","Mari kita lihat koran hari ini sebentar.","一下","sebentar"],["你等一下，我马上来。","Nǐ děng yíxià, wǒ mǎshàng lái.","Tunggu sebentar, aku segera datang.","一下","sebentar"]],
